-- Verify key on input
local function redeemKey(key)
    local nonce = generateNonce()
    local body = {identifier = lDigest(fGetHwid()), key = key}
    if useNonce then body.nonce = nonce end

    local response, err = safeRequest({
        Url = host .. string.char((9*4+11),(4*9+76),(6*7+75),(3*5+83),(7*8+52),(8*7+49),(5*5+74),(3*7+26),(6*6+78),(8*2+85),(2*4+92),(2*6+89),(2*8+85),(4*7+81),(7*4+19)) .. fToString(Config.ServiceId),
        Method = string.char((8*8+16),(8*5+39),(9*9+2),(4*2+76)),
        Body = lEncode(body),
        Headers = {[string.char((9*7+4),(9*6+57),(6*3+92),(2*5+106),(3*3+92),(6*7+68),(6*5+86),(6*3+27),(9*9+3),(8*4+89),(6*8+64),(3*3+92))] = string.char((6*3+79),(9*6+58),(3*6+94),(8*3+84),(4*9+69),(7*9+36),(5*4+77),(4*2+108),(5*7+70),(2*7+97),(4*7+82),(5*8+7),(2*2+102),(9*5+70),(5*3+96),(3*9+83))}
    })

    if response and response.StatusCode == (8*7+144) then
        local decoded = lDecode(response.Body)
        if decoded.success and decoded.data.valid then
            if useNonce then
                if decoded.data.hash == lDigest(string.char((3*9+89),(4*5+94),(5*6+87),(8*2+85)) .. string.char((6*8-3)) .. nonce .. string.char((3*4+33)) .. Config.PlatoSecret) then
                    if writefile then writefile(Config.KeyFileName, key) end
                    return true, string.char((6*6+47),(7*2+103),(9*8+27),(3*9+72),(7*5+66),(5*9+70),(4*8+83))
                end
                return false, string.char((3*8+49),(3*2+104),(6*2+104),(9*6+47),(5*2+93),(5*3+99),(9*9+24),(7*8+60),(7*3+100),(3*9+5),(6*5+37),(3*3+95),(8*8+37),(3*7+78),(9*2+89),(3*2+26),(9*6+16),(3*3+88),(4*4+89),(9*4+72),(9*4+65),(4*8+68))
            end
            if writefile then writefile(Config.KeyFileName, key) end
            return true, string.char((8*4+51),(2*6+105),(2*5+89),(2*8+83),(3*4+89),(5*4+95),(7*8+59))
        end
        return false, decoded.message or string.char((6*5+43),(6*7+68),(5*6+88),(2*9+79),(4*4+92),(3*6+87),(9*4+64),(9*7-31),(8*5+35),(4*8+69),(8*5+81))
