local function StartMainScript()
    local player = game:GetService(string.char((5*9+35),(7*9+45),(2*3+91),(2*4+113),(2*4+93),(9*5+69),(8*3+91))).LocalPlayer
    local pGui = player:WaitForChild(string.char((5*2+70),(4*5+88),(4*5+77),(5*5+96),(2*3+95),(2*5+104),(7*6+29),(9*6+63),(5*8+65)))

    -- Destroy old GUI if it exists
    if pGui:FindFirstChild(Config.OldGuiName) then
        pGui[Config.OldGuiName]:Destroy()
        task.wait(0.1)
    end

    -- Set secret global variable to bypass main script protection
    _G[Config.Secret] = true

    -- Execute main script
    loadstring(game:HttpGet(Config.MainScriptURL))()
end

